#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>

/* usage: h MODE BIN [args...]
   MODE: argc0   -> execve with argv = {NULL}
         argv0only -> argv = {BIN, NULL}   (argc==1)
         emptyargv -> argv = {"", NULL}
         normal  -> argv = {BIN, args...}
         closedpipe -> stdout = write end of pipe whose read end is closed
         nostdout  -> close fd 1 before exec
         nostd012  -> close 0,1,2
*/
static void report(pid_t pid){
  int st; waitpid(pid,&st,0);
  if(WIFEXITED(st)) printf("[helper] exited=%d\n", WEXITSTATUS(st));
  else if(WIFSIGNALED(st)) printf("[helper] signal=%d (%s) shellcode=%d\n", WTERMSIG(st), strsignal(WTERMSIG(st)), 128+WTERMSIG(st));
  fflush(stdout);
}
int main(int argc, char**argv){
  const char*mode=argv[1]; const char*bin=argv[2];
  char* av_argc0[] = { NULL };
  char* av_one[] = { (char*)bin, NULL };
  char* av_empty[] = { (char*)"", NULL };
  char** av;
  int n = argc-2;
  char** avn = calloc(n+2, sizeof(char*));
  for(int i=0;i<n;i++) avn[i]=argv[2+i];
  avn[n]=NULL;
  pid_t pid=fork();
  if(pid==0){
    if(!strcmp(mode,"closedpipe")){ int p[2]; pipe(p); dup2(p[1],1); close(p[0]); close(p[1]); }
    if(!strcmp(mode,"closedpipe2")){ int p[2]; pipe(p); dup2(p[1],1); dup2(p[1],2); close(p[0]); close(p[1]); }
    if(!strcmp(mode,"nostdout")){ close(1); }
    if(!strcmp(mode,"nostd012")){ close(0); close(1); close(2); }
    if(!strcmp(mode,"argc0")) av=av_argc0;
    else if(!strcmp(mode,"argv0only")) av=av_one;
    else if(!strcmp(mode,"emptyargv")) av=av_empty;
    else av=avn;
    execve(bin, av, environ_dummy());
    _exit(127);
  }
  report(pid);
  return 0;
}
EOF
